import{_ as t,o,c as s,a0 as r}from"./chunks/framework.ChlVJx0I.js";const f=JSON.parse('{"title":"Resource descriptions are read from the source file","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0030-resource-descriptions-read-from-the-source-file.md","filePath":"adr/0030-resource-descriptions-read-from-the-source-file.md","lastUpdated":1790709292000}'),i={name:"adr/0030-resource-descriptions-read-from-the-source-file.md"};function n(a,e,d,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="resource-descriptions-are-read-from-the-source-file" tabindex="-1">Resource descriptions are read from the source file <a class="header-anchor" href="#resource-descriptions-are-read-from-the-source-file" aria-label="Permalink to &quot;Resource descriptions are read from the source file&quot;">​</a></h1><p>The toggle&#39;s lists, the new resource picker, and the argument completion must show what a resource does, not only its name. pi carries a standard description for two of the four kinds: a skill&#39;s SKILL.md frontmatter <code>description</code>, and a prompt template&#39;s frontmatter <code>description</code> with the first non-empty line as the fallback. Themes have no description field, and extensions have no description anywhere in pi. We decided: the toggle derives one Resource description per resource from the source file itself - the frontmatter for a skill, the frontmatter or first line for a prompt template, nothing for a theme, and the leading block comment of the entry file for an extension. The text is read only: the toggle never writes it.</p><h2 id="considered-options" tabindex="-1">Considered Options <a class="header-anchor" href="#considered-options" aria-label="Permalink to &quot;Considered Options&quot;">​</a></h2><ul><li><strong>Source-file derivation (chosen).</strong> It works for disabled resources and untrusted projects, adds no file format, and matches the two kinds pi already standardizes. For an extension, the leading block comment is the first thing an author writes about the file, so it serves as the description without a new convention to teach.</li><li><strong>A README beside the entry file.</strong> A README is documentation, not a one-liner; choosing which line is the description is arbitrary, and most extensions carry no README at all.</li><li><strong>Runtime registrations (the commands and tools the extension registers).</strong> They exist only while the extension is loaded, so a disabled extension - exactly the row a user is about to disable - has nothing to show.</li><li><strong>No description.</strong> The state before this decision: name and path alone, which do not say what disabling removes.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>The leading block comment of an extension entry file becomes a soft contract: it is the description the lists, the picker, and the completion show. An author who wants a description writes the comment; an author who does not gets none, never a wrong one.</li><li>Extraction is display-side only. The description is not settings state, not part of the state machine, and never written to a file.</li><li>A skill description may run to 1024 chars, so the resolver keeps the full collapsed text and every display surface caps what it prints.</li></ul>',6)])])}const u=t(i,[["render",n]]);export{f as __pageData,u as default};
